class _MeshCoreBleScanWorker(QObject):
    finished = Signal(tuple)
    progress = Signal(tuple)
    cancelled = Signal()
    failed = Signal(str)

    def __init__(self, timeout_sec: int) -> None:
        super().__init__()
        self.timeout_sec = max(5, int(timeout_sec))
        self._cancel_event = threading.Event()

    def request_cancel(self) -> None:
        """Request cancellation without waiting for this worker's thread event loop."""

        self._cancel_event.set()

    def _report_progress(self, advertisements: tuple[MeshCoreBleAdvertisement, ...]) -> None:
        self.progress.emit(tuple(advertisements))

    def run(self) -> None:
        try:
            self.finished.emit(
                tuple(
                    discover_meshcore_ble_devices(
                        self.timeout_sec,
                        cancel_event=self._cancel_event,
                        progress_callback=self._report_progress,
                    )
                )
            )
        except MeshOperationCancelled:
            self.cancelled.emit()
        except Exception as exc:
            self.failed.emit(str(exc))


class _SoftwareAutofillWorker(QObject):
    """One bounded filesystem-discovery request running off the UI thread."""

    finished = Signal(int, str, object)
    cancelled = Signal(int)
    failed = Signal(int, str, str)

    def __init__(
        self,
        coordinator: GuidedSoftwareDiscoveryCoordinator,
        request: DiscoveryRequest,
        section: str,
        *,
        js8_port: str = "",
        profile_name: str = "",
    ) -> None:
        super().__init__()
        self.coordinator = coordinator
        self.request = request
        self.generation = int(request.generation)
        self.section = str(section or "").strip().lower()
        self.js8_port = str(js8_port or "").strip()
        self.profile_name = str(profile_name or "").strip()
        self._cancel_event = threading.Event()

    def request_cancel(self) -> None:
        self._cancel_event.set()
        self.coordinator.cancel(self.request.session_key, self.request.generation)

    def run(self) -> None:
        try:
            if self._cancel_event.is_set():
                self.cancelled.emit(self.generation)
                return
            snapshot = self.coordinator.discover(
                self.request,
                cancel_probe=self._cancel_event.is_set,
            )
            payload = legacy_payload_from_snapshot(snapshot)
            _merge_legacy_application_results(payload)
            if bool(payload.get("cancelled")):
                self.cancelled.emit(self.generation)
                return
            candidates: List[Dict[str, Any]] = []
            if self.section == "fast_light":
                results = dict(payload.get("fast_results") or {})
                flrig = results.get("path_flrig")
                fldigi = results.get("path_fldigi")
                if (flrig and flrig.path) or (fldigi and fldigi.path):
                    candidates.append(
                        {
                            "family_key": "fast_light",
                            "name": "Detected Fast Light installation",
                            "application_path": flrig.path if flrig else "",
                            "secondary_application_path": fldigi.path if fldigi else "",
                            "host": "127.0.0.1",
                            "port": 12345,
                            "secondary_port": 7362,
                            "storage_path": getattr(results.get("fldigi_log_path"), "path", ""),
                            "provenance": "detected",
                        }
                    )
            elif self.section == "varac":
                results = dict(payload.get("varac_results") or {})
                install = results.get("varac_path")
                if install and install.path:
                    candidates.append(
                        {
                            "family_key": "varac",
                            "name": "Detected VarAC installation",
                            "application_path": install.path,
                            "configuration_path": getattr(results.get("varac_ini_path"), "path", ""),
                            "storage_path": getattr(results.get("varac_db_path"), "path", ""),
                            "secondary_storage_path": getattr(results.get("message_paths.varac"), "path", ""),
                            "outbox_path": getattr(results.get("varac_outbox_dir"), "path", ""),
                            "provenance": "detected",
                        }
                    )
            elif self.section == "js8":
                results = dict(payload.get("js8_results") or {})
                profiles = tuple(payload.get("js8_file_profiles") or ())
                install_candidates = tuple(payload.get("install_candidates") or ())
                install_path = next(
                    (
                        str(getattr(candidate, "path", "") or "")
                        for candidate in install_candidates
                        if str(getattr(candidate, "app_id", "") or "").strip().casefold() == "js8call"
                    ),
                    "",
                )
                if install_path:
                    results["path_js8call"] = PathDetectionResult(
                        key="path_js8call",
                        label="JS8Call application path",
                        path=install_path,
                        confidence="detected",
                        reason="Detected by the guided application scan.",
                        exists=Path(install_path).exists(),
                        target_type="file",
                    )
                for profile in profiles:
                    try:
                        tcp_port = int(profile.tcp_server_port or 2442)
                    except (TypeError, ValueError):
                        tcp_port = 2442
                    candidates.append(
                        {
                            "family_key": "js8call",
                            "name": profile.operator_label,
                            "host": "127.0.0.1",
                            "port": tcp_port,
                            "udp_port": 2242,
                            "rig_name": profile.rig_name,
                            "application_path": install_path,
                            "configuration_path": profile.ini_path,
                            "storage_path": profile.application_data_root,
                            "provenance": "detected",
                            "storage_mode": profile.storage_mode,
                        }
                    )
                selected = select_js8call_file_profile(
                    profiles,
                    tcp_port=self.js8_port,
                    profile_name=self.profile_name,
                )
                if selected is not None:
                    results["js8_directed_path"] = PathDetectionResult(
                        key="js8_directed_path",
                        label="JS8Call DIRECTED.TXT path",
                        path=selected.directed_path,
                        confidence=selected.confidence,
                        reason=selected.reason,
                        exists=Path(selected.directed_path).is_file(),
                        target_type="file",
                    )
                elif sum(1 for profile in profiles if profile.directed_path) > 1:
                    results["js8_directed_path"] = PathDetectionResult(
                        key="js8_directed_path",
                        label="JS8Call DIRECTED.TXT path",
                        path="",
                        confidence="not_found",
                        reason=(
                            "Multiple JS8Call profiles contain DIRECTED.TXT, but none matched "
                            f"the selected radio's TCP port {self.js8_port or '--'}."
                        ),
                        exists=False,
                        target_type="file",
                    )
            else:
                results = {}
            results["__instance_candidates__"] = candidates
            if self._cancel_event.is_set():
                self.cancelled.emit(self.generation)
                return
            self.finished.emit(self.generation, self.section, dict(results))
        except Exception as exc:
            self.failed.emit(self.generation, self.section, str(exc))


