            if hasattr(self, "varac_bbs_vault_description_edit"):
                self.varac_bbs_vault_description_edit.clear()
            if hasattr(self, "varac_bbs_vault_source_dir_edit"):
                self.varac_bbs_vault_source_dir_edit.clear()
