        def _guard_flag(key):
            value = profile.get(key)
            if value is None:
                settings = getattr(self, "settings", None)
                value = settings.get(key, True) if settings is not None else True
            if isinstance(value, str):
                return value.strip().lower() not in {"", "0", "false", "no", "off"}
